    _catalog = FINAL_BOSS_TRANSLATIONS[_language]
    _catalog["boss.solution"] = _solution
    _catalog["boss.offender"] = _offender
    _catalog["boss.rules"] = "\n\n".join(
        _catalog[f"boss.rules_{section}"]
        for section in ("intro", "phases", "win", "loss", "archive")
    )
